#!/usr/bin/env bash
# read-only status of ExIt it8 fits/evals on 01/04/08
for h in 127x01 127x04 127x08; do ssh -o ConnectTimeout=10 $h 'J=/mpac/sdicks02/jobs/clasher/bot-exit-r1$( [ $(hostname) = 127x08 ] || echo -${HOSTNAME#127x}); echo "== $(hostname) py=$(pgrep -c python) load=$(cut -d" " -f1 /proc/loadavg) gpu=$(nvidia-smi --query-gpu=utilization.gpu,memory.used --format=csv,noheader) users=$(who | grep -vc sdicks02)"
for d in $J/train-A* $J/train-B*; do [ -d $d ] || continue; s=$(tail -1 $d/train.jsonl 2>/dev/null | grep -oE "\"step\": [0-9]+" | head -1); echo "  fit $(basename $d) $s $([ -e $d/complete.json ] && echo DONE)"; done
for n in kmix2r kmix2 kmixg8b kmix3r kmix3 kcA4 ksM3 kmixg8a A3x300s1 A3x300s2 A3x800s1 A3x800s2 A1x300s1 A1x300s2 A1x800s1 A1x800s2 B6s1 B6s2 B8s1 B8s2 B6s1-3000 B8s1-3000 B6s3 B6s4; do d=$J/ce-$n; [ -d $d ] || continue; g=$(cat $d/eval/games-*.jsonl 2>/dev/null | wc -l); r=$(ls -d $d/cal/rate-* 2>/dev/null | wc -l); echo "  eval $n cal_rounds=$r games=$g/900"; done'; done
